const BASE = 'ꀀ'; // YI SYLLABLE IT: L, PVALID, no canonical compositions
const skip = new Set([0x00,0x09,0x0a,0x0d,0x2e,0x3002,0xff0e,0xff61]);
const lines = [];
const push = (cp) => {
  if (skip.has(cp)) return;
  if (cp >= 0xd800 && cp <= 0xdfff) return;
  lines.push(cp.toString(16) + '\t' + BASE + String.fromCodePoint(cp) + BASE);
};
for (let cp = 1; cp <= 0x32fff; cp++) push(cp);
for (let cp = 0xe0000; cp <= 0xe01ff; cp++) push(cp);
// sparse sample of the skipped high planes to confirm all-DISALLOWED
for (let cp = 0x33000; cp <= 0x10ffff; cp += 419) push(cp);
writeFileSync('/tmp/probe/inputA.txt', lines.join('\n') + '\n');
console.log('total', lines.length);
EOF
node /tmp/probe/gen_a.mjs

cd /tmp/probe && cat > analyze.mjs <<'EOF'
