const cls = new Map();
for (const line of readFileSync('classA.txt','utf8').trim().split('\n')) {
  const [h,c] = line.split('\t'); cls.set(parseInt(h,16), c);
}
for (const line of readFileSync('outQ_00.txt','utf8').trim().split('\n')) {} // noop
// merge corrected Q results
import { readdirSync } from 'node:fs';
for (const f of readdirSync('.').filter(f=>f.startsWith('outQ_'))) {
  for (const line of readFileSync(f,'utf8').trim().split('\n')) {
    const [h,c] = line.split('\t'); cls.set(parseInt(h,16), c==='N' ? 'D' : c);
  }
}
// check coverage of the dense range
