  elif [[ $out == *"in a right-to-left label"* && $out == *"Invalid direction"* ]]; then t=BIDI_RTL
  elif [[ $out == *"Can not mix numeral types"* ]]; then t=BIDI_MIX
  elif [[ $out == *"ends with illegal codepoint directionality"* ]]; then t=BIDI_END
  elif [[ $out == *"First codepoint in label"* ]]; then t=BIDI_FIRST
  elif [[ $out == *"Unknown directionality"* ]]; then t=BIDI_UNK
  elif [[ $out == *"adjacent to joiner"* ]]; then t=JOIN
  elif [[ $out == *"InvalidCodepointContext:"* ]]; then t=CTXO
  elif [[ $out == *"InvalidCodepoint:"* ]]; then t=INVCP
  elif [[ $out == *"Normalization Form C"* ]]; then t=NFC
  elif [[ $out == *"illegal combining character"* ]]; then t=COMB
  elif [[ $out == *"hyphen"* ]]; then t=HYPH
  elif [[ $out == *"Empty Label"* ]]; then t=EMPTY
  elif [[ $out == *"too long"* ]]; then t=LONG
  else t=OTHER; fi
