/**
 * Python exception objects, modelled closely enough to reproduce CPython's
 * unhandled-exception report on stderr.
 *
 * The Python side raises `idna.core.IDNAError` and friends, which derive from
 * `UnicodeError` -> `ValueError`.  That inheritance is not cosmetic: `check_label`
 * wraps its CONTEXTJ test in `try: ... except ValueError:`, so an
 * `InvalidCodepointContext` raised inside the `try` is swallowed and re-raised as a
 * plain `IDNAError`.  Reproducing the hierarchy keeps that quirk honest.
 */

/** A frame as rendered by CPython's traceback module. */
export class PyFrame {
  /**
   * @param {string} file   value printed inside `File "..."`
   * @param {number} line   1-based line number
   * @param {string} func   function name printed after `in`
   * @param {string} [src]  source text (only available for the top-level script)
   * @param {string} [caret] the `^^^^` marker line that Python 3.11+ prints
   */
  constructor(file, line, func, src, caret) {
    this.file = file;
    this.line = line;
    this.func = func;
    this.src = src;
    this.caret = caret;
  }
}

/** Base for every Python exception we need to model. */
export class PyException extends Error {
  /**
   * @param {string} pyType  dotted name printed on the final traceback line
   * @param {string} message exception message
   * @param {PyFrame[]} frames innermost-last, as Python prints them
   */
  constructor(pyType, message, frames = []) {
    super(message);
    this.name = pyType;
    this.pyType = pyType;
    this.pyMessage = message;
    this.frames = frames;
    /** @type {PyException|null} the `__context__` chain ("During handling ...") */
    this.context = null;
    /** extra lines printed after the exception line (codec chaining) */
    this.trailer = null;
  }
}

export class ValueErrorPy extends PyException {}
export class UnicodeErrorPy extends ValueErrorPy {}

export class IDNAError extends UnicodeErrorPy {
  constructor(message, frames) {
    super('idna.core.IDNAError', message, frames);
  }
}

export class IDNABidiError extends IDNAError {
  constructor(message, frames) {
    super(message, frames);
    this.name = this.pyType = 'idna.core.IDNABidiError';
  }
}

export class InvalidCodepoint extends IDNAError {
  constructor(message, frames) {
    super(message, frames);
    this.name = this.pyType = 'idna.core.InvalidCodepoint';
  }
}

export class InvalidCodepointContext extends IDNAError {
  constructor(message, frames) {
    super(message, frames);
    this.name = this.pyType = 'idna.core.InvalidCodepointContext';
  }
}

/** `UnicodeError` as raised by the stdlib punycode codec. */
export class PunycodeError extends UnicodeErrorPy {
  constructor(message, frames) {
    super('UnicodeError', message, frames);
  }
}

/** `IndexError`, raised by punycode.py when it walks off the end of the input. */
export class IndexErrorPy extends PyException {
  constructor(message, frames) {
    super('IndexError', message, frames);
  }
}

/**
 * Prepend a caller frame onto a Python exception as it propagates, mirroring the
 * way CPython grows a traceback on the way out.
 *
 * @template T
 * @param {() => T} fn
 * @param {PyFrame} frame the *call site* inside the calling function
 * @returns {T}
 */
export function withFrame(fn, frame) {
  try {
    return fn();
  } catch (err) {
    if (err instanceof PyException) err.frames.unshift(frame);
    throw err;
  }
}

