/**
 * Faithful re-implementations of the pieces of CPython's object model that are
 * observable on this program's output: `bytes.__repr__`, `str.__repr__`,
 * `str.isprintable()` and `print()`.
 */

import { PY_UNKNOWN_CODEPOINTS } from './unicode-tables.mjs';

/**
 * A Python `bytes` value.
 *
 * Every byte string this program produces comes from `str.encode('ascii')`, so the
 * payload is always ASCII; it is still stored as raw byte values so that
 * `bytesRepr` can be exercised on arbitrary input.
 */
export class PyBytes {
  /** @param {string} raw one JS char per byte, each char code in 0..255 */
  constructor(raw = '') {
    this.raw = raw;
  }

  get length() {
    return this.raw.length;
  }

  /** ASCII-only lowercase, exactly like `bytes.lower()`. */
  lower() {
    let out = '';
    for (let i = 0; i < this.raw.length; i++) {
      const c = this.raw.charCodeAt(i);
      out += c >= 0x41 && c <= 0x5a ? String.fromCharCode(c + 0x20) : this.raw[i];
    }
    return new PyBytes(out);
  }

  startsWith(prefix) {
    return this.raw.startsWith(prefix);
  }

  slice(start, end) {
    return new PyBytes(this.raw.slice(start, end));
  }

  concat(other) {
    return new PyBytes(this.raw + (other instanceof PyBytes ? other.raw : other));
  }

  /** `bytes.decode('ascii')` / `bytes.decode('utf-8')` for ASCII payloads. */
  decodeAscii() {
    return this.raw;
  }

  static join(sep, parts) {
    return new PyBytes(parts.map((p) => p.raw).join(sep));
  }

  /** `str.encode('ascii')`; returns null where Python raises UnicodeEncodeError. */
  static fromAscii(str) {
    for (const ch of str) if (ch.codePointAt(0) > 0x7f) return null;
    return new PyBytes(str);
  }
}

// Python's rule: a codepoint is non-printable when its general category is one of
// Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs -- with U+0020 carved out as printable.
const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Zl}\p{Zp}\p{Zs}]$|^\P{Assigned}$/u;

/**
 * `str.isprintable()` for a single codepoint.
 * @param {number} cp
 */
export function isPrintable(cp) {
  if (cp === 0x20) return true;
  // The reference interpreter ships an older Unicode database than this runtime
  // does; anything it does not know about is category Cn, hence not printable.
  if (PY_UNKNOWN_CODEPOINTS.has(cp)) return false;
  return !NON_PRINTABLE.test(String.fromCodePoint(cp));
}

const hex = (n, width) => n.toString(16).padStart(width, '0');

/**
 * CPython's quote selection: prefer `'`, switch to `"` when the value contains a
 * single quote but no double quote.
 */
function pickQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? '"' : "'";
}

/**
 * `repr()` of a Python `bytes` object.
 * @param {PyBytes|string|Uint8Array|number[]} value
 */
export function bytesRepr(value) {
  let raw;
  if (value instanceof PyBytes) raw = value.raw;
  else if (typeof value === 'string') raw = value;
  else raw = Array.from(value, (b) => String.fromCharCode(b)).join('');

  const quote = pickQuote(raw.includes("'"), raw.includes('"'));
  let out = 'b' + quote;
  for (let i = 0; i < raw.length; i++) {
    const b = raw.charCodeAt(i) & 0xff;
    const ch = String.fromCharCode(b);
    if (ch === quote || ch === '\\') out += '\\' + ch;
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b < 0x20 || b >= 0x7f) out += '\\x' + hex(b, 2);
    else out += ch;
  }
  return out + quote;
}

/**
 * `repr()` of a Python `str` object.
 * @param {string} s
 */
export function strRepr(s) {
  const quote = pickQuote(s.includes("'"), s.includes('"'));
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === quote || ch === '\\') out += '\\' + ch;
    else if (cp === 0x09) out += '\\t';
    else if (cp === 0x0a) out += '\\n';
    else if (cp === 0x0d) out += '\\r';
    else if (isPrintable(cp)) out += ch;
    else if (cp < 0x100) out += '\\x' + hex(cp, 2);
    else if (cp < 0x10000) out += '\\u' + hex(cp, 4);
    else out += '\\U' + hex(cp, 8);
  }
  return out + quote;
}

/**
 * `repr()` dispatch for the two value kinds this program prints.
 * @param {PyBytes|string} value
 */
export function pyRepr(value) {
  return value instanceof PyBytes ? bytesRepr(value) : strRepr(value);
}

/**
 * `print(value)` — `str` objects print themselves, everything else prints its repr.
 * @param {PyBytes|string} value
 */
export function pyPrint(value) {
  writeOut((typeof value === 'string' ? value : pyRepr(value)) + '\n');
}

const outChunks = [];
const errChunks = [];

export function writeOut(text) {
  outChunks.push(text);
}

export function writeErr(text) {
  errChunks.push(text);
}

/**
 * Flush both streams and terminate with `code`.
 *
 * Buffering and then writing synchronously keeps ordering deterministic and, more
 * importantly, guarantees nothing is dropped: `process.exit()` truncates pending
 * asynchronous writes on a pipe.
 */
export function flushAndExit(code) {
  const write = (fd, chunks) => {
    if (!chunks.length) return;
    const buf = Buffer.from(chunks.join(''), 'utf8');
    let off = 0;
    while (off < buf.length) {
      try {
        off += writeSyncSafe(fd, buf, off);
      } catch (err) {
        if (err && (err.code === 'EAGAIN' || err.code === 'EINTR')) continue;
        if (err && err.code === 'EPIPE') return;
        throw err;
      }
    }
  };
  write(1, outChunks);
  write(2, errChunks);
  outChunks.length = 0;
  errChunks.length = 0;
  process.exit(code);
}

let fsWriteSync = null;
function writeSyncSafe(fd, buf, off) {
  if (!fsWriteSync) {
    // Loaded lazily so that the common path never pays for the module.
    fsWriteSync = globalThis.__idnaWriteSync;
  }
  return fsWriteSync(fd, buf, off, buf.length - off);
}

/** Installed by the entry point so this module needs no static node: import. */
export function installWriteSync(fn) {
  globalThis.__idnaWriteSync = fn;
  fsWriteSync = fn;
}

