    extended = ascii.toUpperCase();
  } else {
    base = ascii.slice(0, pos);
    extended = ascii.slice(pos + 1).toUpperCase();
  }
  return insertionSort(codepoints(base), extended);
}

/** Frames the codec machinery adds between `ulabel` and the failing helper. */
export const PUNYCODE_CODEC_FRAMES = [
  new PyFrame(PUNYCODE_PY, 207, 'decode'),
  new PyFrame(PUNYCODE_PY, 194, 'punycode_decode'),
  new PyFrame(PUNYCODE_PY, 164, 'insertion_sort'),
];

