/**
 * Codepoint set membership over sorted, non-overlapping ranges.
 *
 * The IDNA tables cover ~142 000 codepoints; storing them as `[start, end]` pairs
 * and binary searching keeps the data module small and lookups O(log n).
 */

/**
 * Test whether `cp` falls inside one of the ranges.
 *
 * @param {number} cp
 * @param {Int32Array|number[]} ranges flat, sorted `[start0, end0, start1, end1, ...]`
 *   where each `end` is inclusive
 * @returns {boolean}
 */
export function rangesContain(cp, ranges) {
  let lo = 0;
  let hi = ranges.length / 2 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < ranges[mid * 2]) hi = mid - 1;
    else if (cp > ranges[mid * 2 + 1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/**
 * Look up a value keyed by codepoint range.
 *
 * @param {number} cp
 * @param {Int32Array|number[]} ranges flat `[start0, end0, value0, start1, ...]`
 * @param {number} fallback returned when `cp` is in no range
 * @returns {number}
 */
export function rangesLookup(cp, ranges, fallback) {
  let lo = 0;
  let hi = ranges.length / 3 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < ranges[mid * 3]) hi = mid - 1;
    else if (cp > ranges[mid * 3 + 1]) lo = mid + 1;
    else return ranges[mid * 3 + 2];
  }
  return fallback;
}

/**
 * Expand a compact "delta run" encoding back into a flat range array.
 *
 * The generated tables store ranges as deltas from the previous range's end,
 * which shrinks the emitted source by roughly 3x compared with absolute values.
 *
 * @param {number[]} deltas alternating `[gapFromPrevEnd, spanLength]`
 * @returns {Int32Array} flat `[start, end]` pairs
 */
export function expandRanges(deltas) {
  const out = new Int32Array(deltas.length);
  let prevEnd = -1;
  for (let i = 0; i < deltas.length; i += 2) {
    const start = prevEnd + deltas[i];
    const end = start + deltas[i + 1];
    out[i] = start;
    out[i + 1] = end;
    prevEnd = end;
  }
  return out;
}

