/**
 * A behavioural re-implementation of the Python `idna` package's `core` module
 * (IDNA 2008 / RFC 5891 + RFC 5892), covering `encode`, `decode`, `alabel` and
 * `ulabel`.
 *
 * Everything here was derived by observing the reference program, including the
 * `idna/core.py` line numbers baked into the raised frames — those are what make
 * the traceback on stderr line up with the original.
 */

import {
  IDNAError,
  IDNABidiError,
  InvalidCodepoint,
  InvalidCodepointContext,
  PunycodeError,
  PyFrame,
  withFrame,
} from './errors.mjs';
import { PyBytes } from './pyrepr.mjs';
import { strRepr } from './pyrepr.mjs';
import { punycodeDecode, punycodeEncode, PUNYCODE_CODEC_FRAMES } from './punycode-codec.mjs';
import { rangesContain } from './intranges.mjs';
import { CONTEXTJ, CONTEXTO, PVALID } from './idna-tables.mjs';
import {
  BIDI_AN,
  BIDI_EN,
  BIDI_L,
  BIDI_NEUTRAL,
  BIDI_NSM,
  BIDI_RAL,
  BIDI_UNKNOWN,
  bidiClassOf,
  isCombiningMark,
  isScript,
  isVirama,
  joiningTypeOf,
} from './unicode-tables.mjs';

const CORE = 'idna/core.py';
const ALABEL_PREFIX = 'xn--';

/** The four codepoints Python's `idna` treats as label separators. */
const DOT_SEPARATORS = new Set([0x002e, 0x3002, 0xff0e, 0xff61]);

/** `_unot()` — how idna formats a codepoint inside an error message. */
function unot(cp) {
  return 'U+' + cp.toString(16).toUpperCase().padStart(4, '0');
}

/** Split a string into codepoints, matching Python's per-character iteration. */
const chars = (s) => Array.from(s);

const frame = (line, func) => new PyFrame(CORE, line, func);

/* --------------------------------------------------------------- validators */

/** `check_bidi()` — RFC 5893. */
export function checkBidi(label, checkLtr = false) {
  const cps = chars(label);
  let bidiLabel = false;
  for (let idx = 0; idx < cps.length; idx++) {
    const dir = bidiClassOf(cps[idx].codePointAt(0));
    if (dir === BIDI_UNKNOWN) {
      // The reference interpreter's `unicodedata` predates its `idna` tables, so
      // a codepoint can be PVALID yet have no directionality at all.
      throw new IDNABidiError(
        `Unknown directionality in label ${strRepr(label)} at position ${idx + 1}`,
        [frame(78, 'check_bidi')],
      );
    }
    if (dir === BIDI_RAL || dir === BIDI_AN) bidiLabel = true;
  }
  if (!bidiLabel && !checkLtr) return true;

  // Bidi rule 1
  const first = bidiClassOf(cps[0].codePointAt(0));
  let rtl;
  if (first === BIDI_RAL) rtl = true;
  else if (first === BIDI_L) rtl = false;
  else {
    throw new IDNABidiError(
      `First codepoint in label ${strRepr(label)} must be directionality L, R or AL`,
      [frame(91, 'check_bidi')],
    );
  }

  let validEnding = false;
  let numberType = null;
  for (let idx = 0; idx < cps.length; idx++) {
    const dir = bidiClassOf(cps[idx].codePointAt(0));
    if (rtl) {
      // Bidi rule 2
      if (dir === BIDI_L) {
        throw new IDNABidiError(
          `Invalid direction for codepoint at position ${idx + 1} in a right-to-left label`,
          [frame(112, 'check_bidi')],
        );
      }
      // Bidi rule 3
      if (dir === BIDI_RAL || dir === BIDI_EN || dir === BIDI_AN) validEnding = true;
      else if (dir !== BIDI_NSM) validEnding = false;
      // Bidi rule 4
      if (dir === BIDI_AN || dir === BIDI_EN) {
        if (!numberType) numberType = dir;
        else if (numberType !== dir) {
          throw new IDNABidiError('Can not mix numeral types in a right-to-left label', [
            frame(124, 'check_bidi'),
          ]);
        }
      }
    } else {
      // Bidi rule 5
      if (dir === BIDI_RAL || dir === BIDI_AN) {
        throw new IDNABidiError(
          `Invalid direction for codepoint at position ${idx + 1} in a left-to-right label`,
          [frame(128, 'check_bidi')],
        );
      }
      // Bidi rule 6
      if (dir === BIDI_L || dir === BIDI_EN) validEnding = true;
      else if (dir !== BIDI_NSM) validEnding = false;
    }
  }
  if (!validEnding) {
    throw new IDNABidiError('Label ends with illegal codepoint directionality', [
      frame(136, 'check_bidi'),
    ]);
  }
  return true;
}

/** `check_initial_combiner()` — the first codepoint must not be a mark. */
export function checkInitialCombiner(label) {
  if (isCombiningMark(label.codePointAt(0))) {
    throw new IDNAError('Label begins with an illegal combining character', [
      frame(143, 'check_initial_combiner'),
    ]);
  }
  return true;
}

/** `check_hyphen_ok()` — RFC 5891 4.2.3.1. */
export function checkHyphenOk(label) {
  const cps = chars(label);
  if (cps.slice(2, 4).join('') === '--') {
    throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position', [
      frame(149, 'check_hyphen_ok'),
    ]);
  }
  if (cps[0] === '-' || cps[cps.length - 1] === '-') {
    throw new IDNAError('Label must not start or end with a hyphen', [
      frame(151, 'check_hyphen_ok'),
    ]);
  }
  return true;
}

/** `check_nfc()` — the label must already be in Normalization Form C. */
export function checkNfc(label) {
  if (label.normalize('NFC') !== label) {
    throw new IDNAError('Label must be in Normalization Form C', [frame(157, 'check_nfc')]);
  }
}

/**
 * `valid_contextj()` — RFC 5892 appendix A.1 (ZWNJ) and A.2 (ZWJ).
 * @param {string[]} cps codepoints of the label
 * @param {number} pos
 */
export function validContextj(cps, pos) {
  const cpValue = cps[pos].codePointAt(0);
  if (cpValue === 0x200c) {
    if (pos > 0 && isVirama(cps[pos - 1].codePointAt(0))) return true;

    let ok = false;
    for (let i = pos - 1; i >= 0; i--) {
      const jt = joiningTypeOf(cps[i].codePointAt(0));
      if (jt === 'T') continue;
      if (jt === 'L' || jt === 'D') {
        ok = true;
        break;
      }
      break;
    }
    if (!ok) return false;

    ok = false;
    for (let i = pos + 1; i < cps.length; i++) {
      const jt = joiningTypeOf(cps[i].codePointAt(0));
      if (jt === 'T') continue;
      if (jt === 'R' || jt === 'D') {
        ok = true;
        break;
      }
      break;
    }
    return ok;
  }
  if (cpValue === 0x200d) {
    return pos > 0 && isVirama(cps[pos - 1].codePointAt(0));
  }
  return false;
}

/**
 * `valid_contexto()` — RFC 5892 appendices A.3 through A.9.
 * @param {string[]} cps codepoints of the label
 * @param {number} pos
 */
export function validContexto(cps, pos) {
  const cpValue = cps[pos].codePointAt(0);

  if (cpValue === 0x00b7) {
    // MIDDLE DOT: only between two U+006C.
    if (pos > 0 && pos < cps.length - 1) {
      return cps[pos - 1].codePointAt(0) === 0x006c && cps[pos + 1].codePointAt(0) === 0x006c;
    }
    return false;
  }
  if (cpValue === 0x0375) {
    // GREEK LOWER NUMERAL SIGN: must be followed by a Greek codepoint.
    if (pos < cps.length - 1 && cps.length > 1) return isScript(cps[pos + 1], 'Greek');
    return false;
  }
  if (cpValue === 0x05f3 || cpValue === 0x05f4) {
    // HEBREW GERESH / GERSHAYIM: must follow a Hebrew codepoint.
    if (pos > 0) return isScript(cps[pos - 1], 'Hebrew');
    return false;
  }
  if (cpValue === 0x30fb) {
    // KATAKANA MIDDLE DOT: the label needs at least one Japanese codepoint.
    for (const cp of cps) {
      if (cp === '・') continue;
      if (isScript(cp, 'Hiragana') || isScript(cp, 'Katakana') || isScript(cp, 'Han')) return true;
    }
    return false;
  }
  if (cpValue >= 0x0660 && cpValue <= 0x0669) {
    // ARABIC-INDIC DIGITS must not be mixed with the extended set.
    for (const cp of cps) {
      const v = cp.codePointAt(0);
      if (v >= 0x06f0 && v <= 0x06f9) return false;
    }
    return true;
  }
  if (cpValue >= 0x06f0 && cpValue <= 0x06f9) {
    // ...and vice versa.
    for (const cp of cps) {
      const v = cp.codePointAt(0);
      if (v >= 0x0660 && v <= 0x0669) return false;
    }
    return true;
  }
  return false;
}

/** `check_label()` — the full per-label validation pipeline. */
export function checkLabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label', [frame(250, 'check_label')]);
  }

  withFrame(() => checkNfc(label), frame(252, 'check_label'));
  withFrame(() => checkHyphenOk(label), frame(253, 'check_label'));
  withFrame(() => checkInitialCombiner(label), frame(254, 'check_label'));

  const cps = chars(label);
  for (let pos = 0; pos < cps.length; pos++) {
    const cpValue = cps[pos].codePointAt(0);
    if (rangesContain(cpValue, PVALID)) continue;

    if (rangesContain(cpValue, CONTEXTJ)) {
      // idna raises InvalidCodepointContext inside a `try: ... except ValueError`.
      // Because IDNAError derives from UnicodeError -> ValueError, that raise is
      // immediately caught by its own handler and re-raised as a plain IDNAError.
      const inner = new InvalidCodepointContext(
        `Joiner ${unot(cpValue)} not allowed at position ${pos + 1} in ${strRepr(label)}`,
        [frame(263, 'check_label')],
      );
      if (!validContextj(cps, pos)) {
        const outer = new IDNAError(
          `Unknown codepoint adjacent to joiner ${unot(cpValue)} at position ${pos + 1} in ${strRepr(label)}`,
          [frame(267, 'check_label')],
        );
        outer.context = inner;
        throw outer;
      }
      continue;
    }

    if (rangesContain(cpValue, CONTEXTO)) {
      if (!validContexto(cps, pos)) {
        throw new InvalidCodepointContext(
          `Codepoint ${unot(cpValue)} not allowed at position ${pos + 1} in ${strRepr(label)}`,
          [frame(274, 'check_label')],
        );
      }
      continue;
    }

    throw new InvalidCodepoint(
      `Codepoint ${unot(cpValue)} at position ${pos + 1} of ${strRepr(label)} not allowed`,
      [frame(278, 'check_label')],
    );
  }

  withFrame(() => checkBidi(label), frame(282, 'check_label'));
}

/* ------------------------------------------------------------------ length */

const validLabelLength = (label) => label.length <= 63;
const validStringLength = (s, trailingDot) => s.length <= (trailingDot ? 254 : 253);

/* ------------------------------------------------------- label conversions */

/**
 * `idna.alabel(label)` — a Unicode label to its ASCII-compatible encoding.
 * @param {string} label
 * @returns {PyBytes}
 */
export function alabel(label) {
  const asAscii = PyBytes.fromAscii(label);
  if (asAscii !== null) {
    // Already ASCII: validate through ulabel but hand back the *original* bytes,
    // so `idna.encode('CAFE.fr')` keeps its capitals.
    withFrame(() => ulabel(asAscii), frame(288, 'alabel'));
    if (!validLabelLength(asAscii)) {
      throw new IDNAError('Label too long', [frame(290, 'alabel')]);
    }
    return asAscii;
  }

  withFrame(() => checkLabel(label), frame(295, 'alabel'));
  const labelBytes = new PyBytes(ALABEL_PREFIX + punycodeEncode(label));
  if (!validLabelLength(labelBytes)) {
    throw new IDNAError('Label too long', [frame(299, 'alabel')]);
  }
  return labelBytes;
}

/**
 * `idna.ulabel(label)` — an A-label (or plain label) back to Unicode.
 * @param {PyBytes|string} label
 * @returns {string}
 */
export function ulabel(label) {
  let labelBytes;
  if (label instanceof PyBytes) {
    labelBytes = label;
  } else {
    const encoded = PyBytes.fromAscii(label);
    if (encoded === null) {
      // Not representable as ASCII: validate the Unicode form and return it.
      checkLabel(label);
      return label;
    }
    labelBytes = encoded;
  }

  labelBytes = labelBytes.lower();
  if (labelBytes.startsWith(ALABEL_PREFIX)) {
    labelBytes = labelBytes.slice(ALABEL_PREFIX.length);
    if (labelBytes.length === 0) {
      throw new IDNAError('Malformed A-label, no Punycode eligible content found', [
        frame(318, 'ulabel'),
      ]);
    }
    if (labelBytes.decodeAscii().slice(-1) === '-') {
      throw new IDNAError('A-label must not end with a hyphen', [frame(320, 'ulabel')]);
    }
  } else {
    withFrame(() => checkLabel(labelBytes.decodeAscii()), frame(322, 'ulabel'));
    return labelBytes.decodeAscii();
  }

  let decoded;
  try {
    decoded = punycodeDecode(labelBytes.decodeAscii());
  } catch (err) {
    if (!(err instanceof PunycodeError)) throw err;
    // The codec machinery inserts its own frames, then idna swallows the
    // UnicodeError and reports a generic failure.
    err.frames.unshift(...PUNYCODE_CODEC_FRAMES);
    err.frames.unshift(frame(326, 'ulabel'));
    err.trailer = "decoding with 'punycode' codec failed";
    const outer = new IDNAError('Invalid A-label', [frame(328, 'ulabel')]);
    outer.context = err;
    throw outer;
  }
  withFrame(() => checkLabel(decoded), frame(329, 'ulabel'));
  return decoded;
}

/* -------------------------------------------------------- domain functions */

/** `_unicode_dots_re.split(s)` — splits on all four separator codepoints. */
function splitLabels(s) {
  const out = [];
  let current = '';
  for (const ch of s) {
    if (DOT_SEPARATORS.has(ch.codePointAt(0))) {
      out.push(current);
      current = '';
    } else {
      current += ch;
    }
  }
  out.push(current);
  return out;
}

/**
 * `idna.encode(s)` — a Unicode domain name to its ASCII form.
 * @param {string} s
 * @returns {PyBytes}
 */
export function encode(s) {
  let trailingDot = false;
  const result = [];
  const labels = splitLabels(s);

  if (labels.length === 0 || (labels.length === 1 && labels[0] === '')) {
    throw new IDNAError('Empty domain', [frame(390, 'encode')]);
  }
  if (labels[labels.length - 1] === '') {
    labels.pop();
    trailingDot = true;
  }
  for (const label of labels) {
    const encoded = withFrame(() => alabel(label), frame(395, 'encode'));
    if (encoded.length) result.push(encoded);
    else throw new IDNAError('Empty label', [frame(397, 'encode')]);
  }
  if (trailingDot) result.push(new PyBytes(''));

  const joined = PyBytes.join('.', result);
  if (!validStringLength(joined, trailingDot)) {
    throw new IDNAError('Domain too long', [frame(404, 'encode')]);
  }
  return joined;
}

/**
 * `idna.decode(s)` — an ASCII domain name back to Unicode.
 * @param {PyBytes|string} s
 * @returns {string}
 */
export function decode(s) {
  const text = s instanceof PyBytes ? s.decodeAscii() : s;
  let trailingDot = false;
  const result = [];
  const labels = splitLabels(text);

  if (labels.length === 0 || (labels.length === 1 && labels[0] === '')) {
    throw new IDNAError('Empty domain', [frame(416, 'decode')]);
  }
  if (labels[labels.length - 1] === '') {
    labels.pop();
    trailingDot = true;
  }
  for (const label of labels) {
    const decoded = withFrame(() => ulabel(label), frame(421, 'decode'));
    if (decoded) result.push(decoded);
    else throw new IDNAError('Empty label', [frame(423, 'decode')]);
  }
  if (trailingDot) result.push('');
  return result.join('.');
}

